INSERT INTO `testomony` (`srno`, `name`, `image`, `designaiton`, `stars`, `content`, `video`, `date`) VALUES
(1, 'Saul Goodman', 'static/img/testimonials/testimonials-1.png', 'Principal/Owner', 5, 'The personalized approach with every project makes them a standout partner. They took the time to understand our specific needs and delivered IP solutions tailored to our industry. The combination of technology expertise and legal insight has made all the difference in protecting our innovations and trademarks on a global scale.', '/static/img/testimonials/videos/video.mp4', '2025-01-09'),
(2, 'Jena Karlis', 'static/img/testimonials/testimonials-3.png', 'Patent attorney', 5, 'I’ve relied on many IP service providers, but none have matched the depth of knowledge and responsiveness. Their team is thorough, and their patent searches are meticulous, helping us strengthen our client cases. I highly recommend for any attorney looking for reliable and efficient IP support.', '', '2025-01-15'),
(3, 'Sarah Williams', 'static/img/testimonials/testimonials-4.png', 'Principal Counsel', 5, 'We rely heavily on EngineerIP for both patent and trademark matters. Their ability to anticipate and address legal hurdles is unmatched. Whether it’s an expedited search or managing a portfolio of trademarks, their precision and insight have proven invaluable time and again. The partnership has been integral to safeguarding our company’s innovations.', '', '2024-10-09'),
(4, 'Sarah Larson', 'static/img/testimonials/testimonials-5.png', 'Senior Counsel', 5, 'The level of detail and commitment that they brings to each project is exceptional. Their patent research goes far beyond basic searches; they provide in-depth analyses that offer strategic advantages. This level of expertise has made them our first choice for intellectual property services, whether for high-stakes patent applications or protecting our global trademarks.', '/static/img/testimonials/videos/video1.mp4', '2025-03-04');

